// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, ERC20, IERC1271} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(uint256 duration, uint256 warpTime) public {
        vm.warp(bound(warpTime, 1000, 1_000_000));
        duration = bound(duration, 1, 10_000 days - 1);

        // maker is an ERC1271 signer contract (adversarial/observing counterparty)
        ERC1271Signer maker = new ERC1271Signer();
        // baseAsset must be a contract; dummy ERC20 that always accepts transfers
        DummyERC20 baseToken = new DummyERC20();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order;
        order.maker = address(maker);
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(baseToken);
        order.strike = 0;
        order.premium = 0;
        order.duration = duration;
        order.expiration = block.timestamp + 100_000 days;
        order.nonce = 0;
        order.whitelist = whitelist;
        order.floorTokens = floorTokens;
        order.erc20Assets = erc20Assets;
        order.erc721Assets = erc721Assets;

        bytes32 orderHash = c.hashOrder(order);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        c.fillOrder(order, "", floorAssetTokenIds);

        // General rule: for a long order, the long position (keyed by the order's own hash)
        // expires at fill time + duration.
        assertTrue(
            c.positionExpirations(uint256(orderHash)) == block.timestamp + duration,
            "long position expiration must be recorded under the order hash"
        );
    }
}

contract ERC1271Signer {
    function isValidSignature(bytes32, bytes memory) external view returns (bytes4) {
        return IERC1271.isValidSignature.selector;
    }
}

contract DummyERC20 {
    function transferFrom(address, address, uint256) external returns (bool) {
        return true;
    }
    function transfer(address, uint256) external returns (bool) {
        return true;
    }
}
